{
  "technical_and_design_decisions": [
    "Module registry will be redesigned from hard-coded bootstrap to a dynamic, pluggable registry backed by a persistent store (e.g., relational database via Spring Data JPA) to support runtime module registration.",
    "Module upload REST API will be implemented as a new controller in spring-cloud-dataflow-admin, accepting multipart file uploads (JAR/ZIP) with metadata validation.",
    "Shell commands for module upload will be added to spring-cloud-dataflow-shell using Spring Shell annotations, delegating to the REST API.",
    "Migrated modules (jms, mail, mongo, mqtt, reactor-ip, stdout) will be moved to spring-cloud-stream-modules (s-c-s-m) repository, updated to Spring Cloud Stream 3.x / Spring Boot 2.5+ baseline, and published as Maven artifacts with proper module metadata (module.yml).",
    "Module metadata format (name, type, version, dependencies, parameters) will be standardized and extracted from module.yml in each module's JAR.",
    "Integration tests will use Testcontainers for external dependencies (ActiveMQ, MongoDB, MQTT broker, etc.) and Spring Cloud Data Flow's test support.",
    "Existing ModuleRegistryPopulator will be refactored to load modules from the dynamic registry at startup and support refresh without restart."
  ],
  "assumptions": [
    "Development team has strong expertise in Spring Framework, Spring Boot, Spring Cloud Stream, and Spring Cloud Data Flow codebases.",
    "Target baseline is Spring Cloud Data Flow 2.8+ / Spring Cloud Stream 3.1+ / Spring Boot 2.5+ / Java 11+.",
    "Module migration includes updating source code, build configuration (Maven/Gradle), tests, and documentation for each module.",
    "Each migrated module will be published as a separate Maven artifact to Spring Milestone/Snapshot repository.",
    "REST API and shell commands will support both module JAR upload and module coordinate (Maven GAV) registration.",
    "Module registry persistence uses the existing SCDF database schema (H2, MySQL, PostgreSQL) with new tables for module definitions.",
    "No UI changes are required in this increment (only shell and REST API).",
    "Security (authentication/authorization) for module upload endpoints leverages existing SCDF security configuration.",
    "Effort estimates assume a single developer working full-time; no parallelization across activities.",
    "Code review, static analysis, and CI pipeline updates are included in each activity."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Design Dynamic Module Registry Architecture",
      "activity_description": "Create technical design for dynamic module registry: data model, persistence strategy, registry interface, bootstrap loading, refresh mechanism, and integration points with module deployment. Document decisions and review with team.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A2",
      "activity_name": "Implement Dynamic Module Registry Backend",
      "activity_description": "Implement new ModuleRegistry interface and JPA-based implementation (ModuleRegistryRepository, ModuleDefinition entity). Refactor ModuleRegistryPopulator to use dynamic registry. Add database migration scripts (Flyway/Liquibase). Unit tests for registry operations.",
      "most_likely_effort": 40
    },
    {
      "activity_id": "A3",
      "activity_name": "Implement Module Upload REST API",
      "activity_description": "Develop REST controller in spring-cloud-dataflow-admin for module upload (POST /modules/upload) and module coordinate registration (POST /modules). Include multipart file handling, module JAR validation, metadata extraction, persistence, and response DTOs. Integration tests with MockMvc.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A4",
      "activity_name": "Implement Shell Commands for Module Upload",
      "activity_description": "Add Spring Shell commands in spring-cloud-dataflow-shell: 'module upload --file <path> [--name <name> --type <type>]' and 'module register --coordinates <gav>'. Implement client-side REST calls, progress indication, and error handling. Unit and integration tests.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A5",
      "activity_name": "Migrate JMS Module from Spring XD to spring-cloud-stream-modules",
      "activity_description": "Migrate jms source/sink modules: update to Spring Cloud Stream 3.x functional API, replace XD-specific code, update dependencies (Spring JMS, ActiveMQ), add module.yml metadata, write integration tests with embedded ActiveMQ, publish artifact.",
      "most_likely_effort": 40
    },
    {
      "activity_id": "A6",
      "activity_name": "Migrate Mail Module from Spring XD to spring-cloud-stream-modules",
      "activity_description": "Migrate mail sink module: update to Spring Cloud Stream 3.x, use Spring Boot Mail starter, add module.yml, integration tests with mock SMTP server (GreenMail), publish artifact.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A7",
      "activity_name": "Migrate Mongo Module from Spring XD to spring-cloud-stream-modules",
      "activity_description": "Migrate mongo source/sink modules: update to Spring Data MongoDB 3.x, reactive vs blocking driver considerations, add module.yml, integration tests with Testcontainers MongoDB, publish artifact.",
      "most_likely_effort": 32
    },
    {
      "activity_id": "A8",
      "activity_name": "Migrate MQTT Module from Spring XD to spring-cloud-stream-modules",
      "activity_description": "Migrate mqtt source/sink modules: update to Eclipse Paho / Spring Integration MQTT 5.x, handle QoS, connection options, add module.yml, integration tests with Testcontainers Mosquitto broker, publish artifact.",
      "most_likely_effort": 32
    },
    {
      "activity_id": "A9",
      "activity_name": "Migrate Reactor-IP Module from Spring XD to spring-cloud-stream-modules",
      "activity_description": "Migrate reactor-ip (TCP/UDP) source/sink modules: update to Reactor Netty / Spring Integration IP, adapt to functional model, add module.yml, integration tests with embedded Netty servers, publish artifact.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A10",
      "activity_name": "Migrate Stdout Module from Spring XD to spring-cloud-stream-modules",
      "activity_description": "Migrate stdout sink module: simple logging sink, update to Spring Cloud Stream 3.x, add module.yml, minimal integration tests, publish artifact.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A11",
      "activity_name": "Integration Testing for Module Upload and Registry",
      "activity_description": "End-to-end integration tests: upload custom module via REST and shell, verify registry persistence, create stream/task definitions using uploaded modules, deploy and validate. Test registry refresh, versioning, and error scenarios. Use Spring Cloud Data Flow test support and Testcontainers.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A12",
      "activity_name": "Documentation and Samples",
      "activity_description": "Update reference documentation: module upload REST API, shell commands, module development guide, migration guide for XD modules. Add sample custom module project. Update release notes.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A13",
      "activity_name": "Code Review, Refactoring, and CI/CD Updates",
      "activity_description": "Peer code reviews for all changes. Refactor based on feedback. Update CI pipelines (GitHub Actions/GitLab CI) for new modules, integration test execution, and artifact publishing. Static analysis (SpotBugs, Checkstyle) compliance.",
      "most_likely_effort": 16
    }
  ],
  "reported_total": {
    "most_likely_effort": 320
  }
}

